{
  "findings": [
    {
      "check_id": "CKV_AZURE_68",
      "title": "Ensure PostgreSQL server log retention is greater than or equal to 7 days",
      "resource": "azurerm_postgresql_configuration.negative1",
      "severity": "MEDIUM",
      "explanation": "The log retention period is set to 5 days, which is less than the recommended minimum of 7 days, potentially leading to loss of important logs."
    }
  ],
  "patched_code": "resource \"azurerm_postgresql_configuration\" \"negative1\" {\n  name                = \"log_retention_days\"\n  resource_group_name = azurerm_resource_group.example.name\n  server_name         = azurerm_postgresql_server.example.name\n  value               = 7\n}",
  "fix_summary": "Increased the PostgreSQL server log retention period from 5 to 7 days to ensure compliance with the recommended minimum retention period."
}
